API Gateway / BFF.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_bff, "API Gateway / BFF") {
    Component(Ingress_Router_Geo_Routing_Middleware, "Ingress Router & Geo-Routing Middleware", "Node.js/Express", "Secures edge ingress, applies rate limiting, and enforces geo-routing.")
    Component(Consent_Enforcement_Proxy, "Consent Enforcement Proxy", "Node.js", "Enforces consent checks at the gateway layer.")
    Component(BFF_Aggregator_Payload_Optimizer, "BFF Aggregator & Payload Optimizer", "Node.js", "Aggregates responses and optimizes payloads for low-bandwidth rural connections.")
}

Rel(Ingress_Router_Geo_Routing_Middleware, Consent_Enforcement_Proxy, "Routes requests for consent validation", "")
Rel(Consent_Enforcement_Proxy, BFF_Aggregator_Payload_Optimizer, "Forwards validated requests", "")

@enduml

Consent & Privacy Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(consent_privacy_service, "Consent & Privacy Service") {
    Component(consent_api_controller, "Consent API Controller", "Go HTTP Handler", "Handles incoming gRPC requests related to user consent and privacy management.")
    Component(privacy_enforcement_engine, "Privacy Enforcement Engine", "Go Business Logic", "Validates and enforces regional data privacy policies, GDPR, and HIPAA compliance rules.")
    Component(consent_data_access_component, "Consent Data Access Component", "Go Database Driver", "Interacts securely with the regional partitioned database to store and retrieve consent records.")
}

Rel(consent_api_controller, privacy_enforcement_engine, "Delegates validation and enforcement of privacy policies", "gRPC / In-Memory")
Rel(privacy_enforcement_engine, consent_data_access_component, "Persists and queries consent records", "Function Call")

@enduml

Regional Databases.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(regional_databases, "Regional Databases") {
    Component(DataPartitionManager, "Data Partition Manager", "PostgreSQL Partitioning", "Manages regional data partitioning to enforce strict data residency compliance.")
    Component(AuditLoggingStore, "Audit Logging Store", "PostgreSQL Append-Only Tables / pgAudit", "Stores immutable audit logs for regulatory compliance and traceability.")
    Component(ConsentIndexer, "Consent Indexer", "PostgreSQL B-Tree/GIN Indexes", "Provides indexing for fast and efficient consent and privacy record retrieval.")
    Component(PatientDataArchivalPurgeManager, "Patient Data Archival & Purge Manager", "PostgreSQL Partition Dropping / Retention Jobs", "Manages data retention policies, archiving, and purging of patient data.")
}

Rel(DataPartitionManager, AuditLoggingStore, "Logs partitioning events")
Rel(ConsentIndexer, DataPartitionManager, "Indexes partitioned consent data")
Rel(PatientDataArchivalPurgeManager, DataPartitionManager, "Executes partition dropping and retention cleanup")
@enduml
